<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { getTool } from '../registry'
import { useToolProcessing } from '../useToolProcessing'
import { aggregateIndicators, deduplicateEntries, deltaMs, enrichTimeline, filterTimeline, flagsToCsv, flagsToMarkdown, formatDuration, formatZone, loadWorkspace, parseEvidenceBlock, saveWorkspace, sortTimeline, tactics, toCsv, toMarkdown, totalDurationMs, type FlagAnswer, type Tactic, type TimelineEntry } from './evidencetimeline'
const { t } = useI18n(); const tool = getTool('soc-tools.evidencetimeline'); type Mode = 'parse' | 'notes' | 'flags'
const mode = ref<Mode>('parse'); const input = ref(''); const processingInput = ref(''); const output = ref(''); const entries = ref<TimelineEntry[]>([]); const flags = ref<FlagAnswer[]>([]); const note = ref(''); const noteHost = ref(''); const noteTactic = ref<Tactic>('other'); const flagLabel = ref(''); const flagValue = ref(''); const flagNotes = ref(''); const tacticFilter = ref<Tactic | 'all'>('all'); const hostFilter = ref(''); const indicatorsOnly = ref(false); const groupByTactic = ref(false); const status = ref(''); const fileInput = ref<HTMLInputElement>()
const hosts = computed(() => [...new Set(entries.value.map((entry) => entry.host).filter(Boolean))].sort()); const sorted = computed(() => sortTimeline(deduplicateEntries(entries.value))); const visible = computed(() => filterTimeline(sorted.value, tacticFilter.value, hostFilter.value, indicatorsOnly.value)); const indicators = computed(() => aggregateIndicators(entries.value)); const dated = computed(() => entries.value.filter((entry) => entry.epochMs !== null).length); const duration = computed(() => totalDurationMs(entries.value)); const groups = computed(() => groupByTactic.value ? tactics.map((tactic) => ({ tactic, items: visible.value.filter((entry) => entry.tactic === tactic) })).filter((group) => group.items.length) : [{ tactic: 'other' as Tactic, items: visible.value }])
function tacticLabel(tactic: Tactic) { return t(`tools.evidencetimeline.tactics.${tactic}`) }; function process() { entries.value = deduplicateEntries(parseEvidenceBlock(processingInput.value)); output.value = 'ok' }; const { inputBytes, isOverLimit, schedule } = useToolProcessing({ input: processingInput, output, maxInputBytes: tool.recommendedMaxInputBytes, process }); watch(input, (value) => { processingInput.value = value; schedule() }, { immediate: true })
function addNote() { if (!note.value.trim()) return; const epochMs = Date.now(); const item = { id: `note-${epochMs}`, epochMs, rawTime: new Date(epochMs).toISOString(), description: note.value.trim(), tactic: noteTactic.value, host: noteHost.value.trim(), source: 'analyst-note', indicators: [] }; entries.value = deduplicateEntries([...entries.value, ...enrichTimeline([item])]); note.value = '' }; function addFlag() { if (!flagLabel.value.trim()) return; flags.value.push({ id: `flag-${Date.now()}`, label: flagLabel.value.trim(), value: flagValue.value.trim(), found: false, notes: flagNotes.value.trim() }); flagLabel.value = ''; flagValue.value = ''; flagNotes.value = '' }; function removeEntry(id: string) { entries.value = entries.value.filter((entry) => entry.id !== id) }; function removeFlag(id: string) { flags.value = flags.value.filter((flag) => flag.id !== id) }; function clearAll() { input.value = ''; entries.value = []; flags.value = []; note.value = ''; status.value = '' }
function download(text: string, name: string, type: string) { const url = URL.createObjectURL(new Blob([text], { type })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = name; anchor.click(); URL.revokeObjectURL(url) }; function exportTimeline(kind: 'csv' | 'json' | 'md') { download(kind === 'csv' ? toCsv(entries.value) : kind === 'json' ? JSON.stringify(entries.value, null, 2) : toMarkdown(entries.value, tacticLabel), `evidence-timeline.${kind}`, kind === 'json' ? 'application/json' : 'text/plain') }; function exportFlags(kind: 'csv' | 'md') { download(kind === 'csv' ? flagsToCsv(flags.value) : flagsToMarkdown(flags.value), `cdsa-flags.${kind}`, 'text/plain') }; async function copy(text: string) { try { await navigator.clipboard.writeText(text); status.value = t('tools.evidencetimeline.copied') } catch { status.value = t('tools.evidencetimeline.copyFailed') } }; function saveFile() { download(saveWorkspace({ entries: entries.value, flags: flags.value }), 'evidence-workspace.json', 'application/json') }; function openFile() { fileInput.value?.click() }; async function loadFile(event: Event) { const element = event.target as HTMLInputElement; const file = element.files?.[0]; if (!file) return; try { const workspace = loadWorkspace(await file.text()); entries.value = workspace.entries; flags.value = workspace.flags; status.value = t('tools.evidencetimeline.loaded') } catch { status.value = t('tools.evidencetimeline.invalidFile') } element.value = '' }; function rowDelta(entry: TimelineEntry) { return formatDuration(deltaMs(sorted.value, sorted.value.indexOf(entry))) }
function timelineJson() { return JSON.stringify(entries.value, null, 2) }
</script>
<template>
  <section class="timeline-shell" :aria-label="t('tools.evidencetimeline.name')">
    <header class="terminal-titlebar"><span>{{ t('tools.evidencetimeline.name') }}</span><span>[SOC]</span></header><div class="toolbar"><div class="mode-switch" :aria-label="t('tools.evidencetimeline.modeLabel')"><button v-for="item in (['parse','notes','flags'] as Mode[])" :key="item" type="button" :aria-pressed="mode === item" @click="mode = item">{{ t(`tools.evidencetimeline.modes.${item}`) }}</button></div><span>{{ inputBytes }} B</span><button class="quiet" type="button" @click="clearAll">{{ t('tools.evidencetimeline.clear') }}</button></div><p class="disclaimer">{{ t('tools.evidencetimeline.disclaimer') }}</p><section v-if="mode === 'parse'" class="input-panel"><h2>{{ t('tools.evidencetimeline.parseHeading') }}</h2><p class="muted">{{ t('tools.evidencetimeline.parseHelp') }}</p><textarea v-model="input" rows="8" spellcheck="false" :placeholder="t('tools.evidencetimeline.parsePlaceholder')" :aria-invalid="isOverLimit" /></section><section v-else-if="mode === 'notes'" class="input-panel"><h2>{{ t('tools.evidencetimeline.notesHeading') }}</h2><div class="form-grid"><label>{{ t('tools.evidencetimeline.observation') }}<input v-model="note" type="text" @keydown.enter="addNote"></label><label>{{ t('tools.evidencetimeline.host') }}<input v-model="noteHost" type="text"></label><label>{{ t('tools.evidencetimeline.tactic') }}<select v-model="noteTactic"><option v-for="tactic in tactics" :key="tactic" :value="tactic">{{ tacticLabel(tactic) }}</option></select></label></div><button class="primary" type="button" @click="addNote">{{ t('tools.evidencetimeline.addObservation') }}</button></section><section v-else class="input-panel"><h2>{{ t('tools.evidencetimeline.flagsHeading') }}</h2><div class="form-grid"><label>{{ t('tools.evidencetimeline.label') }}<input v-model="flagLabel" type="text"></label><label>{{ t('tools.evidencetimeline.value') }}<input v-model="flagValue" type="text"></label><label>{{ t('tools.evidencetimeline.notes') }}<input v-model="flagNotes" type="text"></label></div><button class="primary" type="button" @click="addFlag">{{ t('tools.evidencetimeline.addFlag') }}</button><p class="summary">{{ t('tools.evidencetimeline.foundCounter', { found: flags.filter((flag) => flag.found).length, total: flags.length }) }}</p><div v-for="flag in flags" :key="flag.id" class="flag-row"><input v-model="flag.found" type="checkbox"><input v-model="flag.label" type="text"><input v-model="flag.value" type="text"><input v-model="flag.notes" type="text"><button class="quiet" type="button" @click="removeFlag(flag.id)">{{ t('tools.evidencetimeline.remove') }}</button></div></section>
    <section v-if="mode !== 'flags'" class="timeline-panel"><div class="section-heading"><h2>{{ t('tools.evidencetimeline.timeline') }}</h2><div class="filters"><label>{{ t('tools.evidencetimeline.tactic') }}<select v-model="tacticFilter"><option value="all">{{ t('tools.evidencetimeline.all') }}</option><option v-for="tactic in tactics" :key="tactic" :value="tactic">{{ tacticLabel(tactic) }}</option></select></label><label>{{ t('tools.evidencetimeline.host') }}<select v-model="hostFilter"><option value="">{{ t('tools.evidencetimeline.all') }}</option><option v-for="host in hosts" :key="host" :value="host">{{ host }}</option></select></label><label class="check"><input v-model="indicatorsOnly" type="checkbox">{{ t('tools.evidencetimeline.indicatorsOnly') }}</label><label class="check"><input v-model="groupByTactic" type="checkbox">{{ t('tools.evidencetimeline.groupByTactic') }}</label></div></div><p class="summary">{{ t('tools.evidencetimeline.summary', { entries: entries.length, dated, undated: entries.length - dated, duration: formatDuration(duration) }) }}</p><div v-for="group in groups" :key="group.tactic"><h3 v-if="groupByTactic">{{ tacticLabel(group.tactic) }}</h3><div v-for="entry in group.items" :key="entry.id" class="timeline-row"><div class="times"><span>{{ entry.epochMs === null ? '—' : new Date(entry.epochMs).toISOString() }}</span><span>{{ formatZone(entry.epochMs, 'Europe/Amsterdam') }}</span><span>{{ t('tools.evidencetimeline.delta') }}: {{ rowDelta(entry) }}</span></div><div><div class="row-meta"><span class="tag">{{ tacticLabel(entry.tactic) }}</span><input v-model="entry.host" class="inline-input" type="text"><select v-model="entry.tactic"><option v-for="tactic in tactics" :key="tactic" :value="tactic">{{ tacticLabel(tactic) }}</option></select><button class="quiet" type="button" @click="removeEntry(entry.id)">{{ t('tools.evidencetimeline.remove') }}</button></div><p class="description">{{ entry.description }}</p><p v-if="entry.indicators.length" class="indicators">{{ entry.indicators.join(' · ') }}</p></div></div></div><p v-if="!visible.length" class="muted">{{ t('tools.evidencetimeline.empty') }}</p><div v-if="indicators.length" class="indicator-list"><h3>{{ t('tools.evidencetimeline.aggregatedIndicators') }}</h3><p>{{ indicators.join(' · ') }}</p></div></section>
    <section class="exports"><h2>{{ t('tools.evidencetimeline.export') }}</h2><div class="button-row"><button type="button" @click="copy(toCsv(entries))">{{ t('tools.evidencetimeline.copyCsv') }}</button><button type="button" @click="copy(timelineJson())">{{ t('tools.evidencetimeline.copyJson') }}</button><button type="button" @click="exportTimeline('csv')">{{ t('tools.evidencetimeline.downloadCsv') }}</button><button type="button" @click="exportTimeline('json')">{{ t('tools.evidencetimeline.downloadJson') }}</button><button type="button" @click="copy(toMarkdown(entries, tacticLabel))">{{ t('tools.evidencetimeline.copyMarkdown') }}</button><button type="button" @click="exportTimeline('md')">{{ t('tools.evidencetimeline.downloadMarkdown') }}</button><button type="button" @click="exportFlags('csv')">{{ t('tools.evidencetimeline.downloadFlagsCsv') }}</button><button type="button" @click="exportFlags('md')">{{ t('tools.evidencetimeline.downloadFlagsMarkdown') }}</button><button type="button" @click="saveFile">{{ t('tools.evidencetimeline.save') }}</button><button type="button" @click="openFile">{{ t('tools.evidencetimeline.load') }}</button><input ref="fileInput" class="visually-hidden" type="file" accept="application/json,.json" @change="loadFile"></div><p class="status" aria-live="polite">{{ status }}</p></section>
  </section>
</template>
<style scoped>.timeline-shell{margin-top:24px;border:1px solid var(--border-hairline);border-radius:8px;background:var(--surface-raised);color:var(--text-primary);overflow:hidden}.terminal-titlebar,.toolbar{display:flex;align-items:center;gap:12px;padding:10px 14px;background:var(--surface-overlay);font-family:var(--font-mono)}.terminal-titlebar{justify-content:space-between;color:var(--text-secondary)}.mode-switch{display:flex;border:1px solid var(--border-strong);border-radius:6px;overflow:hidden}.mode-switch button,.button-row button,.primary,.quiet{min-height:44px;padding:8px 13px;border:1px solid var(--border-strong);border-radius:5px;background:var(--surface-overlay);color:var(--text-primary);font:inherit;cursor:pointer}.mode-switch button{border:0;border-right:1px solid var(--border-strong);border-radius:0}.mode-switch button[aria-pressed=true]{background:var(--accent-muted);color:var(--accent-strong)}.toolbar .quiet{margin-left:auto}.muted,.summary,.status{color:var(--text-muted)}.disclaimer,.input-panel,.timeline-panel,.exports{padding:16px 24px}.input-panel,.timeline-panel,.exports{border-top:1px solid var(--border-hairline)}h2{margin:0 0 8px;font-size:1.1rem}h3{margin:16px 0 8px;font-size:1rem}textarea,input,select{box-sizing:border-box;width:100%;min-height:44px;border:1px solid var(--border-strong);border-radius:5px;background:var(--surface-overlay);color:var(--text-primary);font:inherit;padding:9px 10px}textarea{resize:vertical}select option{background:var(--surface-overlay);color:var(--text-primary)}label{display:flex;flex-direction:column;gap:6px;color:var(--text-primary)}.form-grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:12px;margin:12px 0}.section-heading{display:flex;justify-content:space-between;gap:16px}.filters,.button-row{display:flex;flex-wrap:wrap;gap:8px}.filters label{min-width:9rem}.check{flex-direction:row;align-items:center;min-height:44px}.check input{width:18px;min-height:18px}.summary{font-family:var(--font-mono)}.timeline-row{display:grid;grid-template-columns:270px 1fr;gap:16px;padding:12px 0;border-top:1px solid var(--border-hairline)}.times{display:flex;flex-direction:column;gap:4px;color:var(--text-muted);font:.82rem var(--font-mono)}.row-meta{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.tag{padding:4px 8px;border:1px solid var(--border-strong);border-radius:999px;background:var(--surface-overlay);color:var(--text-muted)}.inline-input{width:12rem}.description{margin:8px 0;white-space:pre-wrap;overflow-wrap:anywhere;color:var(--text-primary)}.indicators,.indicator-list p{color:var(--text-muted);overflow-wrap:anywhere}.flag-row{display:grid;grid-template-columns:28px 1fr 1fr 2fr auto;gap:8px;align-items:center;padding:8px 0;border-top:1px solid var(--border-hairline)}.button-row button{color:var(--accent)}.visually-hidden{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid var(--accent);outline-offset:2px}@media(max-width:768px){.disclaimer,.input-panel,.timeline-panel,.exports{padding-inline:16px}.section-heading{display:block}.filters{margin-top:12px}.timeline-row{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}}@media(max-width:560px){.toolbar{align-items:stretch;flex-direction:column}.toolbar .quiet{margin-left:0}.flag-row{grid-template-columns:28px 1fr}.flag-row input:not([type=checkbox]),.flag-row .quiet{grid-column:2}.row-meta{align-items:stretch;flex-direction:column}.inline-input{width:100%}}</style>
function timelineJson() { return JSON.stringify(entries.value, null, 2) }
